<div style={{flex:1,minWidth:0}}><div style={{fontSize:12,fontWeight:700}}>{tk(p.ticker)||p.name||p.mint?.slice(0,8)}</div><div style={{fontSize:9,color:T.ft}}>{p.amount>1e9?(p.amount/1e9).toFixed(1)+"B":p.amount>1e6?(p.amount/1e6).toFixed(1)+"M":fm(p.amount)}</div></div>
