<div style={{display:"flex",gap:4,marginBottom:10}}>{PRESETS.map(p=>{const ac=sol===p.sol&&snc===p.snc;return<button key={p.name} onClick={()=>applyPreset(p)} className="hl" style={{flex:1,padding:"10px 0",background:ac?T.gn+"0c":T.bg,border:"1px solid "+(ac?T.gn+"33":T.bd),borderRadius:8,cursor:"pointer",textAlign:"center"}}><div style={{fontSize:14,fontWeight:800,color:ac?T.gn:T.tx}}>{p.name}</div><div style={{fontSize:9,color:T.ft,marginTop:2}}>{p.sol} SOL</div></button>})}</div>
