{showKeys&&<div style={{position:"fixed",inset:0,background:"rgba(0,0,0,.65)",zIndex:100,display:"flex",alignItems:"center",justifyContent:"center",padding:12,animation:"fi .15s ease"}} onClick={()=>sShowKeys(false)}><div onClick={e=>e.stopPropagation()} style={{background:T.sf,border:"1px solid "+T.gn+"22",borderRadius:16,padding:20,maxWidth:420,width:"100%",animation:"si .2s ease"}}><div style={{display:"flex",alignItems:"center",justifyContent:"space-between",marginBottom:14}}><span style={{fontWeight:800,fontSize:16}}>Settings</span><button onClick={()=>sShowKeys(false)} style={{background:"none",border:"none",color:T.ft,fontSize:18,cursor:"pointer"}}>×</button></div>{trW&&<div style={{marginBottom:12}}><div style={{fontSize:9,fontWeight:700,color:T.ft,textTransform:"uppercase",marginBottom:4}}>Trading Key</div><div onClick={()=>{navigator.clipboard?.writeText(trW);toast("Copied","success")}} style={{padding:"8px 10px",background:T.bg,border:"1px solid "+T.bd,borderRadius:8,fontSize:12,color:T.gn,cursor:"pointer",wordBreak:"break-all"}}>{trW}</div><div style={{display:"flex",gap:4,marginTop:6}}><button onClick={async()=>{try{const r=await a.etw(user.pubkey);if(r.ok&&r.privateKey){navigator.clipboard?.writeText(r.privateKey);toast("Key copied — clears 60s","success");setTimeout(()=>navigator.clipboard?.writeText(""),60000)}}catch(e){toast(e.message,"error")}}} style={{flex:1,padding:"6px 0",background:T.yl+"0c",border:"1px solid "+T.yl+"22",borderRadius:6,fontSize:10,fontWeight:700,color:T.yl,cursor:"pointer"}}><IC.key s={12} c={T.yl}/> Export Key</button><button onClick={async()=>{try{const r=await a.er(user.pubkey);toast(`${r.totalWallets} wallets | ${fs(r.totalSol,4)} SOL`,"success")}catch(e){toast(e.message,"error")}}} style={{flex:1,padding:"6px 0",background:T.or+"0c",border:"1px solid "+T.or+"22",borderRadius:6,fontSize:10,fontWeight:700,color:T.or,cursor:"pointer"}}>Emergency</button></div></div>}<div style={{fontSize:10,color:T.ft,textAlign:"center"}}>SOL ${solP.toFixed(2)}</div></div></div>}

